function captureFamily(){
 const form=document.querySelector('#registration-form');if(!form)return;
 const fields=new FormData(form);familyDraft={...familyDraft,...Object.fromEntries(fields),children:[...form.querySelectorAll('.registration-child')].map(card=>({first_name:card.querySelector('[data-child-field="first_name"]').value,last_name:card.querySelector('[data-child-field="last_name"]').value,age:card.querySelector('[data-child-field="age"]').value,group_ids:[...card.querySelectorAll('input[type=checkbox]:checked')].map(input=>input.value)}))};
}
async function registration(){
 const params=new URLSearchParams(location.hash.split('?')[1]||'');
 if(registrationRequestHash!==location.hash){const language=params.get('language');if(translations[language])registerLocale=language;registrationRequestHash=location.hash;familyDraft=null;}
 const data=state||await api('/public/programs'),t=translations[registerLocale],f=familyCopy[registerLocale];
 if(!familyDraft){const requestedGroup=params.get('group'),requestedProgram=params.get('program');const initialGroups=data.groups.filter(g=>requestedGroup===g.id||(!requestedGroup&&g.program_id===requestedProgram&&data.groups.filter(item=>item.program_id===g.program_id).length===1)).map(g=>g.id);familyDraft={guardian_name:'',email:'',phone:'',language:registerLocale,neighborhood:'Little Havana',guardian_id:'',children:[{first_name:'',last_name:'',age:'',group_ids:initialGroups}]};}
 const d=familyDraft;
 const field=(id,label,name,value,extra='')=>`<div class="field"><label for="${id}">${E(label)}</label><input id="${id}" name="${name}" value="${E(value)}" ${extra}></div>`;
 const childCards=d.children.map((child,index)=>`<fieldset class="registration-child" data-child-index="${index}"><legend>${E(f.child)} ${index+1}</legend><div class="form-grid">${['first_name','last_name','age'].map((key,i)=>`<div class="field"><label for="child-${index}-${key}">${E([t.child,t.last,t.age][i])}</label><input id="child-${index}-${key}" data-child-field="${key}" value="${E(child[key])}" ${key==='age'?'type="number" min="0" max="18"':'maxlength="80" autocomplete="off"'} required></div>`).join('')}<fieldset class="field full program-choices"><legend>${E(t.programs)}</legend>${data.groups.map(g=>{const p=data.programs.find(p=>p.id===g.program_id);return `<label class="check-row"><input type="checkbox" value="${g.id}" ${child.group_ids.includes(g.id)?'checked':''}><span><strong>${E(g.name)}</strong><br><span class="muted small">${E(g.neighborhood)} · ${E(g.weekday)} · ${E(g.time)} · ${E(t.age)} ${p.min_age}–${p.max_age}</span></span></label>`;}).join('')}<p class="small muted">${E(f.choose)}</p></fieldset></div>${d.children.length>1?`<button class="btn small" type="button" data-action="remove-child" data-id="${index}" aria-label="${E(f.remove)} ${index+1}">${E(f.remove)}</button>`:''}</fieldset>`).join('');
 const form=`<div class="toolbar"><span class="small muted">English · Español · Kreyòl ayisyen</span><div><label for="registration-locale">Form language / Idioma / Lang</label><select id="registration-locale">${Object.keys(translations).map(l=>`<option ${l===registerLocale?'selected':''}>${l}</option>`).join('')}</select></div></div>`+panel(t.title,f.description,`<div class="panel-body"><p class="callout info">${E(t.note)}</p><form id="registration-form"><h3 class="registration-section-title">${E(f.guardianSection)}</h3><div class="form-grid">${state?.user.role==='manager'?`<div class="field full"><label for="existing-guardian">Household link (staff only)</label><select id="existing-guardian" name="guardian_id"><option value="">Create a new household · review possible duplicates separately</option>${state.guardians.map(g=>`<option value="${g.id}" ${d.guardian_id===g.id?'selected':''}>${E(g.name)} · ${E(g.email)}</option>`).join('')}</select><span class="hint">Link only when you have confirmed the family’s identity.</span></div>`:''}${field('reg-guardian',t.guardian,'guardian_name',d.guardian_name,'required maxlength="120" autocomplete="name"')}${field('reg-email',t.email,'email',d.email,'type="email" required maxlength="200" autocomplete="email"')}${field('reg-phone',t.phone,'phone',d.phone,'type="tel" maxlength="40" autocomplete="tel"')}<div class="field"><label for="reg-neighborhood">${E(t.neighborhood)}</label><select id="reg-neighborhood" name="neighborhood">${['Little Havana','West Little River'].map(n=>`<option ${n===d.neighborhood?'selected':''}>${n}</option>`).join('')}</select></div><div class="field full"><label for="reg-language">${E(t.language)}</label><select id="reg-language" name="language">${Object.keys(translations).map(l=>`<option ${l===d.language?'selected':''}>${l}</option>`).join('')}</select></div></div><h3 class="registration-section-title">${E(f.childSection)}</h3><p class="small muted" aria-live="polite">${E(f.count(d.children.length))}</p><div id="registration-children">${childCards}</div><button class="btn" type="button" data-action="add-child" ${d.children.length>=10?'disabled':''}>${icon('plus')}${E(f.add)}</button>${d.children.length>=10?`<p class="small muted">${E(f.limit)}</p>`:''}<p class="small muted counseling-note">${E(f.counseling)}</p><div class="form-actions"><button class="btn primary" type="submit">${E(f.submit)}</button></div><p class="error-text" id="page-error" role="alert"></p></form></div>`);
 if(state)shell(heading('Family registration','One guardian, with individual program choices for every child.')+form,'register');
 else app.innerHTML=`<div class="topbar public-topbar">${brand()}<a class="btn" href="#login">Staff sign in</a></div><main class="content" id="main" data-page="register" style="max-width:800px">${form}</main>`;
}

