function updateManualPrograms(){const id=document.querySelector('#manual-student').value;const programs=state.programs.filter(p=>state.enrollments.some(e=>e.student_id===id&&e.program_id===p.id));document.querySelector('#manual-program').innerHTML=programs.map(p=>`<option value="${p.id}">${E(p.name)}</option>`).join('');}
async function assessmentForm(studentId='',programId='',phase=''){
 studentId=studentId||state.students[0].id;assessmentDetail=await api('/students/'+encodeURIComponent(studentId));
 const programs=state.programs.filter(p=>JSON.parse(p.details).attendance_rule==='consecutive_absences'&&state.enrollments.some(e=>e.student_id===studentId&&e.program_id===p.id));
 showDialog('Record program self-assessment',`<p>Voluntary, non-clinical feedback. Use the program’s existing question and 1–5 scale; never fill in an unanswered assessment.</p><form id="assessment-form"><div class="form-grid"><div class="field full"><label for="assessment-student">Participant</label><select id="assessment-student" name="student_id">${state.students.map(s=>`<option value="${s.id}" ${s.id===studentId?'selected':''}>${E(name(s))}</option>`).join('')}</select></div><div class="field full"><label for="assessment-program">Program</label><select id="assessment-program" name="program_id" required>${programs.length?'':'<option value="">No eligible program enrollment</option>'}${programs.map(p=>`<option value="${p.id}">${E(p.name)}</option>`).join('')}</select><p class="small muted" id="assessment-question"></p></div><div class="field"><label for="assessment-phase">Phase</label><select id="assessment-phase" name="phase"><option value="start">Start</option><option value="end">End</option></select></div><div class="field"><label for="assessment-score">Reported score (1–5)</label><select id="assessment-score" name="score" required><option value="">Choose reported score</option>${[1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select></div><div class="field"><label for="assessment-date">Date recorded</label><input id="assessment-date" type="date" name="recorded_at" min="${state.config.quarter_start}" max="${state.config.quarter_end}" required></div><input type="hidden" name="expected" id="assessment-expected"><div class="field full" id="assessment-correction" hidden><label class="check-row"><input type="checkbox" name="replace"><span>I confirm this is a correction to the existing assessment. The previous value will remain in the audit history.</span></label></div></div><div class="form-actions"><button class="btn primary" type="submit" ${programs.length?'':'disabled'}>Save assessment</button></div></form>`);if(programId)document.querySelector('#assessment-program').value=programId;if(phase)document.querySelector('#assessment-phase').value=phase;updateAssessmentFields();
}
function updateAssessmentFields(){const program=document.querySelector('#assessment-program').value,phase=document.querySelector('#assessment-phase').value,old=assessmentDetail.assessments.find(a=>a.program_id===program&&a.phase===phase),p=state.programs.find(p=>p.id===program);document.querySelector('#assessment-question').textContent=p?`Measure: ${p.outcome_label}`:'';document.querySelector('#assessment-score').value=old?.score||'';document.querySelector('#assessment-date').value=old?.recorded_at||state.config.demo_today;document.querySelector('#assessment-expected').value=old?JSON.stringify([old.score,old.recorded_at]):'';document.querySelector('#assessment-correction').hidden=!old;document.querySelector('[name=replace]').checked=false;}
function importPage(){
 shell(heading('Bring your signup sheet together.','Preview a CSV, confirm family matches, then import once. Existing identities and attendance are never overwritten.',`<a class="btn" href="#participants">Back to participants</a>`)+panel('1. Choose a signup CSV','Export a sheet as CSV. Import up to 20 rows / 20 KB per batch.',`<div class="panel-body"><p>Required columns: <code>source_system, source_id, guardian_name, email, language, neighborhood, first_name, last_name, age, group_id</code>. Optional: <code>phone</code>. Keep source IDs stable between imports.</p><p class="small muted">This imports family signups and program enrollment. It does not import historical attendance or connect directly to Google Sheets.</p><p><a href="/samples/tidepath-messy-signups.csv" download>Download a fictional messy example</a> · <a href="/samples/tidepath-signup-template.csv" download>Download blank template</a></p><label for="intake-file">CSV file</label><input id="intake-file" type="file" accept=".csv,text/csv"><div class="form-actions">${btn('Preview and find possible matches','preview-import','search',true)}</div></div>`)+`<div id="import-preview"></div>`,'import');if(intakePreview)renderImportPreview();
}
async function previewImportFile(){const file=document.querySelector('#intake-file').files[0];if(!file)throw new Error('Choose a CSV file first.');if(file.size>20000)throw new Error('Keep the CSV under 20 KB and 20 rows.');intakeCSV=await file.text();intakePreview=await post('/import/preview',{csv:intakeCSV});renderImportPreview();}
function renderImportPreview(){document.querySelector('#import-preview').innerHTML=panel('2. Confirm identities','Suggestions are clues, not confirmed matches. Choose a guardian and child for every new source row.',`<div class="panel-body"><p class="callout info">Matching an existing record preserves its canonical name, contact details, language and age. Different names or emails can still belong to the same person—confirm with the family. No match is selected automatically.</p>${intakePreview.rows.map(r=>`<article class="import-row" data-import-row="${r.index}"><h3>Row ${r.index+1}: ${E(r.first_name)} ${E(r.last_name)}</h3><p>${E(r.guardian_name)} · ${E(r.email)} · ${E(r.language)}<br><span class="small muted">Age ${r.age} · ${E(r.group_id)} · Source ${E(r.source_system)}/${E(r.source_id)}</span></p>${r.already_imported?'<p class="badge success">Already imported — will be skipped</p>':`<p class="small muted">${r.candidates.length?r.candidates.map(c=>`${E(c.name)}: ${E(c.signals.join(', '))}`).join(' · '):'No existing match found. You can still choose a confirmed existing guardian.'}${r.earlier_rows.length?` · Possible related rows: ${r.earlier_rows.map(i=>i+1).join(', ')}`:''}</p><div class="form-grid"><div class="field"><label for="import-guardian-${r.index}">Confirm guardian / household</label><select id="import-guardian-${r.index}" data-import-guardian="${r.index}"><option value="">Choose after reviewing</option><option value="new">Create new guardian and household</option>${intakePreview.rows.slice(0,r.index).map(p=>`<option value="row:${p.index}">Use guardian confirmed for row ${p.index+1}</option>`).join('')}${state.guardians.map(g=>`<option value="${g.id}">${E(g.name)} · ${E(g.email)}</option>`).join('')}</select></div><div class="field"><label for="import-child-${r.index}">Confirm child</label><select id="import-child-${r.index}"><option value="">Confirm the guardian first</option></select></div></div>`}</article>`).join('')}<label class="check-row"><input id="import-confirm" type="checkbox"><span>I have reviewed each identity choice and confirm the selected matches. Import creates or links records; it does not overwrite existing profiles.</span></label><div class="form-actions">${btn('Import confirmed rows','commit-import','check',true)}</div></div>`);}
function updateImportChildren(index){const guardian=document.querySelector(`#import-guardian-${index}`).value,select=document.querySelector(`#import-child-${index}`);let canonical=guardian;const seen=new Set();while(canonical.startsWith('row:')){const n=Number(canonical.slice(4));if(seen.has(n))break;seen.add(n);canonical=document.querySelector(`#import-guardian-${n}`)?.value||'';}
 const existing=state.students.filter(s=>state.links.some(l=>l.student_id===s.id&&l.guardian_id===canonical));
 select.innerHTML=guardian?`<option value="">Choose after reviewing</option><option value="new">Create a new child</option>${intakePreview.rows.slice(0,index).map(r=>`<option value="row:${r.index}">Use child confirmed for row ${r.index+1}: ${E(r.first_name)} ${E(r.last_name)}</option>`).join('')}${existing.map(s=>`<option value="${s.id}">${E(name(s))} · age ${s.age}</option>`).join('')}`:'<option value="">Confirm the guardian first</option>';
 // A changed guardian invalidates decisions in later rows that may reference it.
 for(let n=index+1;n<intakePreview.rows.length;n++){const input=document.querySelector(`#import-child-${n}`);if(input)input.value='';}
}
async function commitImportFile(){if(!intakePreview)throw new Error('Preview a CSV first.');if(!document.querySelector('#import-confirm').checked)throw new Error('Confirm that you reviewed the identity choices.');const decisions=intakePreview.rows.map(r=>r.already_imported?{}:{guardian:document.querySelector(`#import-guardian-${r.index}`).value,child:document.querySelector(`#import-child-${r.index}`).value});if(decisions.some((d,i)=>!intakePreview.rows[i].already_imported&&(!d.guardian||!d.child)))throw new Error('Choose a guardian and child for every new row.');const result=await post('/import/commit',{csv:intakeCSV,decisions});intakePreview=null;intakeCSV='';await refresh(false);document.querySelector('#import-preview').innerHTML=empty('Import completed',`${result.imported} source rows imported; ${result.skipped} already-imported rows skipped. Created ${result.new_households} households, ${result.new_children} children and ${result.new_enrollments} enrollments. Existing profiles and historical attendance were preserved.`,`<a class="btn" href="#participants">View participants</a>`);}

function showDialog(title,body){dialog.innerHTML=`<div class="dialog-header"><h2>${E(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close detail">${icon('close')}</button></div><div class="dialog-body">${body}<p class="error-text" role="alert"></p></div>`;if(!dialog.open)dialog.showModal();}
function renderLogin(){
  app.innerHTML=`<div class="login-shell"><section class="login-story">${brand()}<div><h1>More time<br>for <em>people.</em></h1><p class="lead">A shared program workspace for the children, families, and people who show up for them.</p></div><figure class="login-photo"><img src="/assets/hero.jpg" alt="Illustrative photo of young people together" width="1800" height="1200"></figure><p class="login-foot">Tidepath Family Alliance<br>Little Havana · West Little River · Miami-Dade</p></section><main class="login-main" id="main"><div class="login-card"><h1>Welcome to TidePath</h1><p>Sign in to your program workspace.</p><form id="login-form"><div class="field"><label for="login-email">Email address</label><input id="login-email" name="email" type="email" required autocomplete="username"></div><div class="field"><label for="login-password">Password</label><input id="login-password" name="password" type="password" required autocomplete="current-password"></div><button class="btn primary" type="submit">Sign in ${icon('arrow')}</button><p class="error-text" id="page-error" role="alert"></p></form>${me?.demo?`<div class="demo-users"><p>Explore the fictional demo. Choose a role to fill the sign-in form.</p><div class="demo-buttons">${[['marisol','Marisol','Program manager'],['elena','Elena','Harbor session leader'],['james','James','Bayview workshop leader'],['priya','Priya','Riverside workshop leader']].map(([id,n,r])=>`<button class="btn" data-action="demo-user" data-id="${id}"><strong>${n}</strong><small>${r}</small></button>`).join('')}</div><p style="margin-top:12px">All records are fictional. No real family information belongs in this demo.</p></div>`:''}<p style="margin-top:24px"><a href="#register">Open family registration ${icon('arrow')}</a></p></div></main></div>`;
}
async function refresh(render=true){state=await api('/state');me={user:state.user,demo:state.demo,ai_available:state.ai_available};reportDraft=null;if(render)await route();}
async function route(){
  const [page,query='']=(location.hash.slice(1)||'overview').split('?');
  if(page==='register'){await registration();return;}
  if(!state){renderLogin();return;}
  const allowed=state.user.role==='teacher'?['attendance']:['overview','programs','participants','attendance','followups','volunteers','reports','import','quarter-close'];
  if(!allowed.includes(page)){location.hash=state.user.role==='teacher'?'attendance':'overview';return;}
  if(page!=='attendance'){roster=null;dirty=false;}
  if(page==='overview')overview();else if(page==='programs')programsPage();else if(page==='participants')participants();else if(page==='attendance'){const id=new URLSearchParams(query).get('session');if(id)await openRoster(id);else attendance();}else if(page==='followups'){followups();const task=new URLSearchParams(query).get('task');if(task)await followupDetail(task);}else if(page==='volunteers')volunteers();else if(page==='reports')reports();else if(page==='import')importPage();else if(page==='quarter-close')await closeQuarter(new URLSearchParams(query).get('snapshot')||'');
}
async function withBusy(button,fn){if(button?.disabled)return;const old=button?.innerHTML;if(button){button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Working…';}try{await fn();}catch(e){error(e.message);}finally{if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=old;}}}
document.addEventListener('click',async event=>{
  if(event.target.closest('.skip')){event.preventDefault();const main=document.querySelector('#main');main?.setAttribute('tabindex','-1');main?.focus();return;}
  const b=event.target.closest('[data-action]');if(!b)return;const {action,id,value}=b.dataset;
  if(action==='close-dialog'){dialog.close();return;}
  if(action==='mark'){marks[id]=value||null;dirty=true;updateMarks();return;}
  if(action==='mark-all'){for(const id in marks)if(marks[id]===null)marks[id]='present';dirty=true;updateMarks();return;}
  if(action==='navigate'){location.hash=b.dataset.page;return;}
  if(action==='demo-user'){document.querySelector('#login-email').value=`${id}@tidepath.example`;document.querySelector('#login-password').value='TidePath-demo-2026!';document.querySelector('#login-form button[type=submit]').focus();return;}
  if(action==='roster'){location.hash='attendance?session='+encodeURIComponent(id);return;}
  if(action==='session-filter'){sessionFilter=value;attendance();return;}
  if(action==='task-filter'){taskFilter=value;followups();return;}
  if(action==='volunteer-tab'){volunteerTab=value;volunteers();return;}
  if(action==='evidence'){evidence(b.dataset.kind);return;}
  if(action==='snapshot-evidence'){evidence(b.dataset.kind,savedSnapshot.report,true);return;}
  if(action==='review-hours'){hoursFilter='pending';volunteerTab='hours';if(location.hash==='#volunteers')volunteers();else location.hash='volunteers';return;}
  if(action==='download-snapshot'){const blob=new Blob([JSON.stringify(savedSnapshot,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`tidepath-${savedSnapshot.report.start}-${savedSnapshot.report.end}-${savedSnapshot.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}
  if(action==='register-again'){familyDraft=null;await registration();return;}
  if(action==='add-child'||action==='remove-child'){captureFamily();if(action==='add-child'&&familyDraft.children.length<10)familyDraft.children.push({first_name:'',last_name:'',age:'',group_ids:[]});else if(action==='remove-child'&&familyDraft.children.length>1)familyDraft.children.splice(Number(id),1);await registration();const index=action==='add-child'?familyDraft.children.length-1:Math.min(Number(id),familyDraft.children.length-1);document.querySelector(`#child-${index}-first_name`)?.focus();return;}
  if(action==='new-hours'){hoursForm();return;}
  if(action==='new-match'){matchForm();return;}
  if(action==='print'){window.print();return;}
  if(action==='download-report'){const blob=new Blob([JSON.stringify(state.report,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='tidepath-q3-2026-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}
  await withBusy(b,async()=>{
    if(action==='run-weekly-check'){await post('/operations/check');await refresh(false);overview();notify('Check completed. In-app reminders are refreshed.');}
    else if(action==='refresh-quarter')await closeQuarter();
    else if(action==='edit-guardian')await guardianContactForm(id,b.dataset.studentId);
    else if(action==='new-followup')manualFollowupForm(id);
    else if(action==='new-assessment')await assessmentForm(id,b.dataset.programId,b.dataset.phase);
    else if(action==='preview-import')await previewImportFile();
    else if(action==='commit-import')await commitImportFile();
    else if(action==='logout'){await post('/logout');state=null;me={...me,user:null};dialog.close();location.hash='login';renderLogin();}
    else if(action==='student')await studentDetail(id);
    else if(action==='program')programDetail(id);
    else if(action==='followup')await followupDetail(id);
    else if(action==='save-roster')await saveRoster();
    else if(action==='draft-report'){reportDraft=await post('/report/draft');reports();}
    else if(action==='draft-followup'){const d=await post('/followups/'+id+'/draft');document.querySelector('#contact-draft').value=d.text;document.querySelector('#draft-source').textContent=`${d.source} · ${d.warning||'Draft in the guardian’s preferred language. Review before use.'}`;}
    else if(action==='simulate-send'){const body=document.querySelector('#contact-draft').value.trim();if(!body)throw new Error('Draft or write a message before recording a simulated send.');await post('/followups/'+id+'/events',{kind:'simulated_send',body});await refresh(false);await followupDetail(id);notify('Simulated contact recorded. No message was sent.');}
    else if(action==='approve-hours'||action==='reject-hours'){await put('/hours/'+id,{status:action==='approve-hours'?'approved':'rejected'});await refresh();}
  });
});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const data=Object.fromEntries(new FormData(form));
  const b=event.submitter||form.querySelector('[type=submit]');await withBusy(b,async()=>{
    if(form.id==='login-form'){await post('/login',data);await refresh(false);location.hash=state.user.role==='teacher'?'attendance':'overview';await route();}
    else if(form.id==='registration-form'){captureFamily();const result=await post('/register',familyDraft),f=familyCopy[registerLocale];familyDraft=null;if(state)await refresh(false);const content=empty(f.success,f.saved(result.children_registered),`<button class="btn" data-action="register-again">${E(f.again)}</button>`);if(state)shell(content,'register');else app.innerHTML=`<main class="content" id="main">${brand()}${content}<a href="#login">Staff sign in</a></main>`;}
    else if(form.id==='quarter-close-form'){data.reviewed=form.querySelector('[name=reviewed]').checked;const result=await post('/quarter/snapshots',data);location.hash='quarter-close?snapshot='+encodeURIComponent(result.id);notify('Dated report version saved with its evidence.');}
    else if(form.id==='guardian-contact-form'){await put('/guardians/'+encodeURIComponent(form.dataset.guardianId),data);await refresh(false);await studentDetail(form.dataset.studentId);notify('Shared guardian contact details updated for all linked children.');}
    else if(form.id==='manual-followup-form'){const result=await post('/followups',data);await refresh(false);await followupDetail(result.id);notify('Follow-up created and assigned.');}
    else if(form.id==='assessment-form'){data.replace=form.querySelector('[name=replace]')?.checked||false;await post('/assessments',data);const id=data.student_id;await refresh(false);await studentDetail(id);notify('Assessment saved. Quarterly results are updated.');}
    else if(form.id==='task-form'){await put('/followups/'+form.dataset.id,data);await refresh(false);notify('Owner, due date, and next action saved.');}
    else if(form.id==='contact-form'){await post('/followups/'+form.dataset.id+'/events',data);await refresh(false);await followupDetail(form.dataset.id);await route();}
    else if(form.id==='hours-form'){await post('/hours',data);dialog.close();await refresh();}
    else if(form.id==='match-form'){await post('/matches',data);dialog.close();await refresh();}
  });
});
document.addEventListener('input',event=>{if(event.target.id==='participant-search'){const el=event.target,pos=el.selectionStart;search=el.value;participants();const input=document.querySelector('#participant-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',async event=>{
  const el=event.target;if(el.id==='manual-student'){updateManualPrograms();}else if(el.id==='assessment-student'){try{await assessmentForm(el.value);}catch(e){error(e.message);}}else if(el.id==='assessment-program'||el.id==='assessment-phase'){updateAssessmentFields();}else if(el.matches('[data-import-guardian]')){updateImportChildren(Number(el.dataset.importGuardian));}else if(el.id==='intake-file'){intakePreview=null;const preview=document.querySelector('#import-preview');if(preview)preview.innerHTML='';}else if(el.id==='program-filter'){programFilter=el.value;participants();}else if(el.id==='group-filter'){programFilter=el.value;attendance();}else if(el.id==='hours-filter'){hoursFilter=el.value;volunteers();}else if(el.id==='registration-locale'){captureFamily();registerLocale=el.value;await registration();}else if(el.id==='existing-guardian'&&el.value){const g=state.guardians.find(g=>g.id===el.value);document.querySelector('#reg-guardian').value=g.name;document.querySelector('#reg-email').value=g.email;document.querySelector('#reg-phone').value=g.phone;document.querySelector('#reg-language').value=g.preferred_language;document.querySelector('#reg-neighborhood').value=state.households.find(h=>h.id===g.household_id)?.neighborhood||'Little Havana';}
});
window.addEventListener('hashchange',()=>{search='';programFilter='';route().catch(e=>error(e.message));});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
for(const event of ['online','offline'])window.addEventListener(event,()=>{const banner=document.querySelector('.offline');if(banner)banner.hidden=navigator.onLine;});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
async function init(){me=await api('/me');if(me.user)await refresh(false);await route();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
init().catch(e=>{app.innerHTML=`<main class="initial" id="main">${brand()}<h1 style="margin-top:24px">TidePath could not open.</h1><p style="margin-top:12px">${E(e.message)}</p><p style="margin-top:12px">Reconnect and reload this page.</p></main>`;});
